-- Product sheet content, 2026-10-12. Descriptions in the FACELIFT esthetician voice.
-- Key ingredients: headline actives only. Natural products and sizes were checked against brand or
-- retailer pages (2026-10-11 research); clinical key ingredients are the actives each product is
-- named and known for. Size is filled only where it was confirmed. Empty = hidden in the app.
update public.product_catalog p set
